const groups={public:['Mapa general','Home','About','Contact','Cursos','Detalle de curso','Blog','Blog post','Blog categories','Search results','404','Coming soon','Login','Recuperar contraseña'],admin:['Dashboard','Registrar usuario','Students','Ficha del estudiante','Instructors','Ficha del instructor','Courses','Detalle y grupos','Vehicles','Ficha del vehículo','Calendario de clases','Detalle de clase','Pagos','Contenido educativo','Banco de preguntas','Reportes y resultados','Usuarios y configuración'],instructor:['Inicio instructor','Mi agenda','Detalle de clase','Mis estudiantes','Ficha y progreso','Mi perfil'],student:['Inicio estudiante','Simulador','Práctica por tema','Examen completo','Resultado y explicación','Mis resultados','Detalle del intento','Material de estudio','Lección o recurso','Mi perfil']};let mode='public',page='Home',answer=null,q=0,score=0;const names={public:'Público',admin:'Administrador',instructor:'Instructor',student:'Estudiante'};const detailTypes={'Ficha del estudiante':'Students','Ficha y progreso':'Students','Ficha del instructor':'Instructors','Detalle y grupos':'Courses','Ficha del vehículo':'Vehicles'};
const recordPrefixes={Students:'EST',Instructors:'INS',Courses:'CUR',Vehicles:'VEH'};
const courseSlugs={'Motocicletas':'motorcycles','Automóviles':'cars','Vehículos pesados':'heavy-vehicles','Transporte de pasajeros':'passenger-transport'};
const recordId=(type,index)=>recordPrefixes[type]+'-'+String(index+1).padStart(3,'0');
const route=(p,m=mode,id)=>{let url='#'+m+'/'+encodeURIComponent(p);if(m==='public'&&p==='Detalle de curso')return url+'?course='+encodeURIComponent(id||'cars');const type=detailTypes[p];return type?url+'?id='+encodeURIComponent(id||recordId(type,0)):url};
const courseRoute=title=>route('Detalle de curso','public',courseSlugs[title]||'cars');
function routeQuery(){return new URLSearchParams(location.hash.split('?')[1]||'')}
function selectedRecord(type){const rows=managementData[type].rows;const id=routeQuery().get('id');const index=rows.findIndex((_,i)=>recordId(type,i)===id);return {row:rows[index<0?0:index],id:recordId(type,index<0?0:index),index:index<0?0:index}}
function personRecordId(name){const i=managementData.Students.rows.findIndex(r=>r[0]===name);return recordId('Students',i<0?0:i)}
const link=(p,t=p,m=mode,id)=>`<a href="${route(p,m,id)}">${t}</a>`;const btn=(p,t=p,m=mode,id)=>`<a class="button" href="${route(p,m,id)}"><button>${t} ↗</button></a>`;const photo=(name,alt)=>`<img class="photo" src="./assets/${name}.jpg" alt="${alt}" loading="lazy">`;const ph=(t='Imagen / recurso visual')=>{let n=t.toLowerCase();if(n.includes('motociclet'))return photo('motorcycle','Motocicleta de referencia');if(n.includes('pesados'))return photo('truck','Vehículo de carga de referencia');if(n.includes('pasajeros'))return photo('bus','Autobús de referencia');if(n.includes('automóviles')||n.includes('vehículos')||n.includes('curso'))return photo('car','Automóvil de referencia');if(n.includes('portada')||n.includes('artículo')||n.includes('instalaciones'))return photo('driving','Interior de un vehículo durante la conducción');return `<div class="placeholder">${t}</div>`};const sec=(t,b)=>{if(b.includes('<details>')){const first=b.indexOf('<details>');const intro=b.slice(0,first);const heading=intro.match(/<h2[^>]*>([\s\S]*?)<\/h2>/);const description=intro.match(/<p[^>]*>([\s\S]*?)<\/p>/);const title=heading?heading[1]:'Preguntas frecuentes';const desc=description?description[1]:'Encuentra respuestas sobre nuestros cursos, tu preparación y cómo comenzar.';const items=b.slice(first).replace(/<summary style="[^"]*">/g,'<summary>').replace('<details>','<details open>');return `<section class="section faq-section" id="faq" tabindex="-1"><div class="faq-intro"><span class="faq-badge">/ FAQ</span><h2>${title}</h2><p>${desc}</p></div><div class="faq-list">${items}</div></section>`}return `<section class="section"><div class="eyebrow">${t}</div>${b}</section>`};const cards=(arr)=>`<div class="grid">${arr.map(([t,p,d])=>`<article class="card">${ph()}<h3>${t}</h3><p>${d||'Descripción breve del contenido y su beneficio principal.'}</p>${btn(p,'Ver detalle')}</article>`).join('')}</div>`;const people=['María López','Carlos Pérez','Ana Martínez','José Ruiz'];function table(type,target){return `<table><thead><tr><th>${type}</th><th>Curso / asignación</th><th>Estado</th><th></th></tr></thead><tbody>${people.map((n,i)=>`<tr><td>${type==='Vehículo'?['Toyota Corolla','Kia Picanto','Hyundai i10','Suzuki Swift'][i]:n}</td><td>${['Curso básico','Clase práctica','Curso intensivo','Teoría vial'][i]}</td><td><span class="tag">${i===2?'Pendiente':'Activo'}</span></td><td>${link(target,'Abrir →')}</td></tr>`).join('')}</tbody></table>`}function fields(items){return items.map(t=>`<label>${t}<input placeholder="${t}" ${t==='Correo electrónico'?'type="email"':''} required></label>`).join('')}const form=(content,text='Guardar cambios')=>`<form onsubmit="event.preventDefault();document.getElementById('feedback').textContent='Cambios guardados en esta demostración.'">${content}<button class="primary">${text}</button><p id="feedback" role="status"></p></form>`;
const courseCategories=[['Motocicletas','Equilibrio, maniobras y conducción segura en dos ruedas.'],['Automóviles','Control del vehículo, estacionamiento y circulación segura.'],['Vehículos pesados','Maniobras, dimensiones y conducción de vehículos de carga.'],['Transporte de pasajeros','Conducción segura y atención al transporte de personas.']];
function courseCards(){return `<div class="grid course-grid">${courseCategories.map(([title,description])=>`<article class="card course-card"><div class="card-visual">${ph('IMAGEN / '+title.toUpperCase())}<span class="card-corner-label">${String(courseCategories.findIndex(c=>c[0]===title)+1).padStart(2,'0')}</span></div><h3>${title}</h3><p>${description}</p><p><span class="tag">Básico</span> <span class="tag">Avanzado</span> <span class="tag">Intensivo</span> <span class="tag">Refuerzo</span></p><a class="course-text-link" href="${courseRoute(title)}" data-course="${courseSlugs[title]}">Ver curso ↗</a></article>`).join('')}</div>`}
function selectedCourse(){const slug=routeQuery().get('course')||'cars';return Object.keys(courseSlugs).find(title=>courseSlugs[title]===slug)||'Automóviles'}

