function courseFaqSection(){const category=selectedCourse();return sec('03 / Preguntas frecuentes',`<h2>Sobre el curso de ${category.toLowerCase()}</h2><p>Resuelve tus dudas antes de comenzar.</p>${(courseFaqs[category]||courseFaqs['Automóviles']).map(([question,answer])=>`<details><summary style="padding:16px 0;border-bottom:1px solid #ddd;cursor:pointer">${question}</summary><p>${answer}</p></details>`).join('')}`)}

