let blogCategory='Todas',blogQuery='',blogPageNumber=1;
function updateBlog(){blogPageNumber=1;animateFiltering(document.getElementById('blog-results'),'article.card',()=>{document.getElementById('blog-results').innerHTML=blogResults()})}
function chooseBlogCategory(category){blogCategory=category;document.querySelectorAll('[data-blog-category]').forEach(b=>{b.classList.toggle('active',b.dataset.blogCategory===category);b.setAttribute('aria-pressed',String(b.dataset.blogCategory===category))});updateBlog()}
function changeBlogPage(n){blogPageNumber=n;document.getElementById('blog-results').innerHTML=blogResults();document.getElementById('blog-results').scrollIntoView({behavior:'smooth',block:'start'});initArticleReveal()}
function blogResults(){const normalize=t=>t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const filtered=blogArticles.filter(a=>(blogCategory==='Todas'||a[1]===blogCategory)&&normalize(a.join(' ')+' '+a.map(t=>translateSiteText(t,'en')).join(' ')).includes(normalize(blogQuery)));const total=Math.max(1,Math.ceil(filtered.length/6));const visible=filtered.slice((blogPageNumber-1)*6,blogPageNumber*6);return `<div class="row"><h2>Artículos más recientes</h2><span class="tag">${filtered.length} artículos</span></div>${visible.length?`<div class="grid">${visible.map(([title,category,date,description])=>`<article class="card" data-flip-id="blog-${blogArticles.findIndex(a=>a[0]===title)}">${ph('PORTADA DEL ARTÍCULO')}<div class="eyebrow">${category}</div><h3>${title}</h3><p>${description}</p><p>${date} · Lectura de ejemplo</p><a class="article-text-link" href="${route('Blog post','public')}">Leer artículo ↗</a></article>`).join('')}</div>`:'<div class="notice"><h3>No encontramos artículos.</h3><p>Prueba otra búsqueda o selecciona una categoría diferente.</p></div>'}<nav aria-label="Paginación de artículos" class="actions"><button onclick="changeBlogPage(${blogPageNumber-1})" ${blogPageNumber===1?'disabled':''}>← Anterior</button>${Array.from({length:total},(_,i)=>`<button ${i+1===blogPageNumber?'class="active" aria-current="page"':''} onclick="changeBlogPage(${i+1})">${i+1}</button>`).join('')}<button onclick="changeBlogPage(${blogPageNumber+1})" ${blogPageNumber===total?'disabled':''}>Siguiente →</button><span style="align-self:center;font-size:12px;color:#767d70">Página ${blogPageNumber} de ${total}</span></nav>`}
function blogToolsSection(){return sec('02 / Explora el blog',`<h2>Encuentra tu próxima lectura.</h2><div class="blog-tools"><div><label for="blog-search">Buscar artículos</label><input id="blog-search" type="search" placeholder="Buscar por título, tema o palabra clave…" oninput="blogQuery=this.value;updateBlog()"></div><div><span style="font-size:12px;color:#6e7767">Categorías</span><div class="actions" role="group" aria-label="Filtrar por categoría">${['Todas','Seguridad vial','Consejos para principiantes','Motocicletas','Automóviles','Vehículos pesados','Transporte de pasajeros'].map(c=>`<button data-blog-category="${c}" aria-pressed="${blogCategory===c}" class="${blogCategory===c?'active':''}" onclick="chooseBlogCategory('${c}')">${c}</button>`).join('')}</div></div></div>`)}
function blogCategoryLanding(){return `<h1>${blogCategory==='Todas'?'Todas las categorías':blogCategory}</h1><p>Explora artículos y consejos para seguir aprendiendo.</p><section class="section"><div id="blog-results" aria-live="polite">${blogResults()}</div></section>`}
function blogLanding(){return `<section class="section hero"><div><div class="eyebrow">01 / Artículo destacado · Seguridad vial</div><h1>Conducir con confianza empieza por aprender.</h1><p>Descubre cómo prepararte para tu primera clase y dar tus primeros pasos al volante con acompañamiento.</p><p>10 nov. 2026 · Artículo de ejemplo</p>${btn('Blog post','Leer artículo destacado')}</div>${ph('IMAGEN DEL ARTÍCULO DESTACADO')}</section>${blogToolsSection()}<section class="section"><div class="eyebrow">03 / Últimas publicaciones</div><div id="blog-results" aria-live="polite">${blogResults()}</div></section>`}

function updateBenefitPosition(){const track=document.getElementById('benefit-track');if(!track)return;const step=track.querySelector('.learning-card').getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap||0);const i=Math.max(0,Math.min(2,Math.round(track.scrollLeft/Math.max(1,track.scrollWidth-track.clientWidth)*2)));document.getElementById('benefit-position').textContent=String(i+1).padStart(2,'0')+' / 03';track.closest('.learning-carousel').dataset.benefit=String(i)}
function moveBenefit(direction){const track=document.getElementById('benefit-track');const step=track.querySelector('.learning-card').getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap||0);const current=Math.round(track.scrollLeft/Math.max(1,track.scrollWidth-track.clientWidth)*2);const target=Math.max(0,Math.min(2,current+direction));if(track._learningTrigger){const trigger=track._learningTrigger;const maximum=track.scrollWidth-track.clientWidth;window.scrollTo({top:trigger.start+(trigger.end-trigger.start)*target/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}else track.scrollTo({left:target*(track.scrollWidth-track.clientWidth)/2,behavior:'smooth'})}

