function labelSharedCards(){document.querySelectorAll('.card,.testimonial-card,.learning-card,.stat').forEach(card=>{if(card.dataset.cardLabel)return;card.dataset.cardLabel=card.classList.contains('testimonial-card')?'Opinión':card.classList.contains('learning-card')?'Aprende':card.classList.contains('stat')||card.classList.contains('school-stat')?'En cifras':card.classList.contains('course-card')?'Formación':'Nexo Drive'})}

let methodResizeObserver;
function initMethodConnections(){if(methodResizeObserver)methodResizeObserver.disconnect();const path=document.querySelector('.method-path');if(!path)return;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('method-connections');svg.setAttribute('aria-hidden','true');path.prepend(svg);function draw(){const box=path.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);const cards=[...path.querySelectorAll('.method-card')];svg.innerHTML=cards.slice(0,-1).map((card,i)=>{const a=card.getBoundingClientRect(),b=cards[i+1].getBoundingClientRect();const x1=a.left-box.left+a.width*.75,y1=a.bottom-box.top+4,x2=b.left-box.left+b.width*.25,y2=b.top-box.top-7,m=(y1+y2)/2;return `<path d="M ${x1} ${y1} C ${x1} ${m}, ${x2} ${m}, ${x2} ${y2}"/><polygon points="${x2-4},${y2-5} ${x2},${y2+2} ${x2+4},${y2-5}"/>`}).join('')}methodResizeObserver=new ResizeObserver(draw);methodResizeObserver.observe(path);requestAnimationFrame(draw)}

function portalIcon(kind='grid'){const paths={grid:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="13" y="3" width="6" height="6" rx="1"/><rect x="3" y="13" width="6" height="6" rx="1"/><rect x="13" y="13" width="6" height="6" rx="1"/>',person:'<circle cx="11" cy="7" r="4"/><path d="M3 21v-3a8 8 0 0 1 16 0v3"/>',book:'<path d="M3 4h7l1 2 1-2h7v15h-7l-1 2-1-2H3zM11 6v15"/>',calendar:'<rect x="3" y="5" width="16" height="15" rx="2"/><path d="M7 2v6M15 2v6M3 10h16"/>',search:'<circle cx="9" cy="9" r="6"/><path d="m14 14 5 5"/>',bell:'<path d="M5 15V9a6 6 0 0 1 12 0v6l2 2H3zM9 20h4"/>',arrow:'<path d="M5 17 17 5M6 5h11v11"/>'};return `<svg width="17" height="17" viewBox="0 0 22 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]||paths.grid}</svg>`}
function portalOverview(){const student=mode==='student';const instructor=mode==='instructor';const metrics=student?[['Progreso teórico','68%','Sigue avanzando','book'],['Prácticas realizadas','12','2 esta semana','calendar'],['Último resultado','80%','↑ 8 puntos','grid'],['Temas por reforzar','3','Tu próxima meta','book']]:instructor?[['Clases de hoy','4','2 completadas','calendar'],['Alumnos asignados','16','Seguimiento activo','person'],['Horas esta semana','24','Agenda planificada','calendar'],['Evaluaciones pendientes','3','Revisa su progreso','book']]:[['Alumnos activos','48','↑ 4 este mes','person'],['Clases programadas','8','Para hoy','calendar'],['Vehículos disponibles','4','Flota activa','grid'],['Pagos pendientes','6','Revisar cobros','book']];const items=student?[['Señales de tránsito','Teoría vial','En progreso',68,'Material de estudio'],['Práctica por tema','Refuerza tus conocimientos','Pendiente',35,'Práctica por tema'],['Examen completo','Evalúa tu preparación','Pendiente',0,'Examen completo'],['Rotondas e intersecciones','Situaciones de circulación','En progreso',42,'Lección o recurso'],['Mis resultados','Revisa tus últimos intentos','Completado',80,'Mis resultados'],['Conducción segura','Material de apoyo','Completado',100,'Lección o recurso']]:[['María López','Automóviles · Básico','Programada',65,'Detalle de clase'],['Carlos Pérez','Motocicletas · Avanzado','Programada',40,'Detalle de clase'],['Ana Martínez','Automóviles · Refuerzo','Completada',90,'Detalle de clase'],['José Ruiz','Vehículos pesados · Básico','Pendiente',25,'Detalle de clase'],['Lucía Torres','Transporte de pasajeros','Programada',55,'Detalle de clase'],['Diego Sánchez','Automóviles · Intensivo','Completada',100,'Detalle de clase']];return `<div class="portal-page-heading"><div><span class="portal-kicker">${student?'MI APRENDIZAJE':instructor?'MI ESPACIO DE TRABAJO':'RESUMEN DE LA ESCUELA'}</span><h1>${student?'Hola, María.':instructor?'Hola, Roberto.':'Todo listo para avanzar.'}</h1><p>${student?'Continúa tu preparación y descubre tu siguiente objetivo.':'Consulta la actividad y organiza los próximos pasos.'}</p></div><span class="portal-date">Datos de demostración</span></div><div class="portal-metrics">${metrics.map(([label,value,note,icon])=>`<article class="portal-metric"><div>${portalIcon(icon)}<span>${label}</span><span class="metric-dots">···</span></div><strong>${value}</strong><small>${note}</small></article>`).join('')}</div><section class="portal-workspace"><div class="portal-workspace-head"><h2>${student?'Tu plan de aprendizaje':'Clases y seguimiento'}</h2>${btn(student?'Simulador':mode==='admin'?'Registrar usuario':'Mi agenda',student?'Iniciar práctica':mode==='admin'?'Registrar usuario':'Ver agenda')}</div><div class="portal-toolbar"><div class="portal-tabs" role="group" aria-label="Filtrar tarjetas">${['Todas',student?'En progreso':'Programada',student?'Pendiente':'Pendiente',student?'Completado':'Completada'].map((t,i)=>`<button class="${i===0?'selected':''}" aria-pressed="${i===0}" onclick="filterPortalStatus('${t}',this)">${t}</button>`).join('')}</div><span id="portal-card-count">6 elementos</span></div><div class="portal-card-grid">${items.map(([name,desc,status,progress,target],i)=>`<article class="portal-task" data-status="${status}"><div class="portal-task-top"><span class="portal-task-icon">${portalIcon(student?'book':'person')}</span><div><h3>${name}</h3><p>${desc}</p></div><span class="portal-status"><i></i>${status}</span></div><div class="portal-task-progress"><span>${student?'Avance del tema':'Progreso del alumno'}</span><strong>${progress}%</strong></div><div class="portal-progress"><span style="width:${progress}%;background:${['#c3d253','#efff36','#a7ba58'][i%3]}"></span></div><div class="portal-task-bottom"><div><small>${student?'Tu siguiente paso':'Instructor'}</small><span>${student?'Continuar aprendiendo':'Roberto García'}</span></div><div><small>${student?'Modalidad':'Próxima clase'}</small><span>${student?'A tu ritmo':['Hoy, 08:00','Hoy, 10:00','Mañana, 09:00'][i%3]}</span></div><a href="${route(target)}" aria-label="Abrir ${name}">${portalIcon('arrow')}</a></div></article>`).join('')}</div><p class="portal-empty" hidden>No hay elementos para este filtro.</p></section>`}
function filterPortalStatus(status,button){const args=arguments;return animateFiltering(document.getElementById('app'),'.portal-task',()=>filterPortalStatusImmediate(...args))}
function filterPortalStatusImmediate(status,button){document.querySelectorAll('.portal-tabs button').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});let count=0;document.querySelectorAll('.portal-task').forEach(card=>{card.hidden=status!=='Todas'&&card.dataset.status!==status;if(!card.hidden)count++});document.getElementById('portal-card-count').textContent=count+' elementos';document.querySelector('.portal-empty').hidden=count>0}
function searchPortal(query){const args=arguments;return animateFiltering(document.getElementById('app'),'.portal-task',()=>searchPortalImmediate(...args))}
function searchPortalImmediate(query){const term=query.trim().toLocaleLowerCase();document.querySelectorAll('#nav>a').forEach(a=>a.hidden=!!term&&!a.textContent.toLocaleLowerCase().includes(term));document.querySelectorAll('.portal-task').forEach(card=>card.hidden=!!term&&!card.textContent.toLocaleLowerCase().includes(term));const count=document.querySelectorAll('.portal-task:not([hidden])').length;const label=document.getElementById('portal-card-count');if(label)label.textContent=count+' elementos';const empty=document.querySelector('.portal-empty');if(empty)empty.hidden=count>0}
function applyPortalShell(){document.body.classList.toggle('auth-mode',mode==='public'&&['Login','Recuperar contraseña'].includes(page));const active=mode!=='public';document.body.classList.toggle('portal-mode',active);const top=document.querySelector('.top');if(!active){top.innerHTML='';return}top.innerHTML=`<div class="portal-search">${portalIcon('search')}<input type="search" placeholder="Buscar en el portal…" aria-label="Buscar en el portal" oninput="searchPortal(this.value)"><span>⌕</span></div><div class="portal-top-actions"><button class="portal-notifications" aria-label="Ver avisos" aria-expanded="false" onclick="const p=document.getElementById('portal-notice');p.hidden=!p.hidden;this.setAttribute('aria-expanded',String(!p.hidden))">${portalIcon('bell')}<i></i></button><a class="portal-profile" href="${route(mode==='admin'?'Usuarios y configuración':'Mi perfil')}"><span class="portal-avatar">${mode==='student'?'ML':mode==='instructor'?'RG':'AD'}</span><span><strong>${mode==='student'?'María López':mode==='instructor'?'Roberto García':'Administración'}</strong><small>${names[mode]}</small></span><span>⌄</span></a></div><div id="portal-notice" hidden><strong>Tu portal está al día</strong><p>Las notificaciones reales estarán disponibles al conectar el sistema.</p></div>`;document.querySelectorAll('#nav>a').forEach((a,i)=>{const text=a.textContent;a.innerHTML=portalIcon(/agenda|Calendario|clase/i.test(text)?'calendar':/Students|Instructors|estudiante|usuario|perfil/i.test(text)?'person':/curso|Courses|Material|Simulador/i.test(text)?'book':'grid')+`<span>${text}</span>`});const nav=document.getElementById('nav');nav.insertAdjacentHTML('beforeend',`<div class="portal-nav-bottom"><a href="${route('Contact','public')}">${portalIcon('person')}<span>Ayuda y soporte</span></a><a href="${route('Login','public')}">${portalIcon('arrow')}<span>Salir del portal</span></a></div>`)}

