function managementMetrics(metrics){return `<div class="manage-metrics">${metrics.map(([label,value],i)=>`<article><span>${portalIcon(['person','calendar','book','grid'][i])}${label}</span><strong>${value}</strong><small>Resumen de ejemplo</small></article>`).join('')}</div>`}
function managementPage(){const d=managementData[page];return `<div class="portal-page-heading"><div><span class="portal-kicker">ADMINISTRACIÓN / ${d.title.toUpperCase()}</span><h1>${d.title}</h1><p>${d.description}</p></div><button class="primary" onclick="openManagementCreate('${page}')">+ ${d.action}</button></div>${managementMetrics(d.metrics)}<section class="manage-panel"><div class="manage-panel-head"><div><h2>${d.title} de la escuela</h2><p>Consulta y actualiza cada ficha.</p></div><span class="manage-counter" id="manage-count">${d.rows.length} registros</span></div><div class="manage-filters"><div class="manage-search">${portalIcon('search')}<input id="manage-search" type="search" placeholder="Buscar ${d.title.toLowerCase()}…" oninput="filterManagement()" aria-label="Buscar ${d.title.toLowerCase()}"></div><select id="manage-status" aria-label="Filtrar por estado" onchange="filterManagement()"><option value="">Todos los estados</option>${[...new Set(d.rows.map(r=>r[4]))].map(t=>`<option>${t}</option>`).join('')}</select><button onclick="document.getElementById('manage-search').value='';document.getElementById('manage-status').value='';filterManagement()">Limpiar filtros</button></div><div class="manage-table-scroll"><table class="manage-table"><thead><tr>${d.columns.map(t=>`<th>${t}</th>`).join('')}<th><span class="manage-sr">Acciones</span></th></tr></thead><tbody>${d.rows.map((row,i)=>`<tr data-manage-status="${row[4]}">${row.map((cell,col)=>`<td>${col===0?`<div class="manage-identity"><span class="manage-avatar">${page==='Vehicles'?portalIcon('grid'):page==='Courses'?portalIcon('book'):cell.split(' ').slice(0,2).map(x=>x[0]).join('')}</span><div><strong>${cell}</strong><small>${page==='Students'?'EST':page==='Instructors'?'INS':page==='Courses'?'CUR':'VEH'}-${String(i+1).padStart(3,'0')}</small></div></div>`:col===4?`<span class="manage-status ${cell==='Pendiente'||cell==='Mantenimiento'?'muted':''}"><i></i>${cell}</span>`:col===3&&page==='Students'?`<div class="manage-progress"><span>${cell}%</span><div><i style="width:${cell}%"></i></div></div>`:cell}</td>`).join('')}<td><a class="manage-open" href="${route(d.target,mode,recordId(page,i))}" aria-label="Abrir ${row[0]}">${portalIcon('arrow')}</a></td></tr>`).join('')}</tbody></table></div><div id="manage-empty" class="manage-empty" hidden>No encontramos registros. Prueba otros filtros.</div><div class="manage-table-footer"><span>Datos ilustrativos de la escuela</span><span>Página 1 de 1</span></div></section><dialog id="management-create" class="manage-dialog"><form onsubmit="event.preventDefault();document.getElementById('create-management-feedback').textContent='Registro preparado en la demostración; no se guarda en una base de datos.'"><div class="manage-panel-head"><h2>${d.action}</h2><button type="button" aria-label="Cerrar" onclick="document.getElementById('management-create').close()">×</button></div>${fields(page==='Courses'?['Nombre del curso','Modalidad']:['Modelo o nombre','Identificación'])}<label>Estado<select><option>Pendiente</option><option>Activo</option></select></label><button class="primary">Preparar registro</button><p id="create-management-feedback" role="status"></p></form></dialog>`}
function openManagementCreate(type){if(type==='Students'||type==='Instructors'){registrationRole=type==='Students'?'Estudiante':'Instructor / Tutor';location.hash=route('Registrar usuario');return}document.getElementById('management-create').showModal()}
function filterManagement(){const args=arguments;return animateFiltering(document.getElementById('app'),'.manage-table tbody tr',()=>filterManagementImmediate(...args))}
function filterManagementImmediate(){const term=document.getElementById('manage-search').value.toLowerCase();const status=document.getElementById('manage-status').value;let n=0;document.querySelectorAll('.manage-table tbody tr').forEach(row=>{row.hidden=!(row.textContent.toLowerCase().includes(term)&&(!status||row.dataset.manageStatus===status));if(!row.hidden)n++});document.getElementById('manage-count').textContent=n+' registros';document.getElementById('manage-empty').hidden=n>0}
function instructorDetailPage(){const {row:r,id,index}=selectedRecord('Instructors');return `<div class="portal-page-heading"><div><span class="portal-kicker">INSTRUCTORES / FICHA</span><h1>Ficha del instructor</h1><p>Información, disponibilidad y seguimiento en un mismo espacio.</p></div>${btn('Instructors','Volver al listado')}</div><div class="manage-detail-layout"><div><section class="manage-panel"><div class="manage-person-hero"><img src="./assets/instructor-${index+1}.jpg" alt="Retrato ilustrativo del instructor"><div><span class="manage-status"><i></i>${r[4]}</span><h2>${r[0]}</h2><p>${r[1]} · ${id}</p></div></div><div class="manage-mini-metrics"><div><strong>${r[3]}</strong><span>Alumnos asignados</span></div><div><strong>24 h</strong><span>Esta semana</span></div><div><strong>4</strong><span>Clases de hoy</span></div></div></section><section class="manage-panel"><div class="reg-section-heading"><span class="reg-step">01</span><div><h2>Datos y disponibilidad</h2><p>Actualiza los datos del perfil.</p></div></div><form onsubmit="event.preventDefault();document.getElementById('instructor-save-status').textContent='Cambios preparados en la demostración.'"><div class="reg-fields"><label>Nombre completo<input value="${r[0]}" required></label><label>Correo electrónico<input type="email" value="instructor@example.com" required></label><label>Teléfono<input type="tel" placeholder="Número por completar"></label><label>Especialidad<select>${courseCategories.map(([t])=>`<option ${t===r[1]?'selected':''}>${t}</option>`).join('')}</select></label><label>Disponibilidad<select>${['Mañana','Tarde','Jornada completa'].map(t=>`<option ${t===r[2]?'selected':''}>${t}</option>`).join('')}</select></label><label>Estado<select>${['Disponible','En clase','Pendiente','Inactivo'].map(t=>`<option ${t===r[4]?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="reg-actions"><button class="primary">Guardar cambios</button></div><p id="instructor-save-status" role="status"></p></form></section><section class="manage-panel"><div class="manage-panel-head"><h2>Estudiantes asignados</h2>${btn('Students','Ver todos')}</div><div class="manage-compact-list">${managementData.Students.rows.filter(student=>student[2]===r[0]).map((student,i)=>{const n=student[0];return`<a href="${route('Ficha del estudiante',mode,personRecordId(n))}"><span class="manage-avatar">${n.split(' ').map(x=>x[0]).join('')}</span><div><strong>${n}</strong><small>Automóviles · ${i===1?'Avanzado':'Básico'}</small></div><span>↗</span></a>`}).join('')}</div></section></div><div class="manage-detail-side"><section class="manage-panel"><h3>Próximas clases</h3>${[['08:00','María López'],['10:00','Carlos Pérez'],['14:00','Lucía Torres']].map(([time,name])=>`<a class="manage-schedule" href="${route('Detalle de clase')}"><span>${time}</span><div><strong>${name}</strong><small>Práctica de conducción</small></div><span>↗</span></a>`).join('')}${btn('Calendario de clases','Abrir calendario')}</section><section class="manage-panel manage-soft-panel"><h3>Vehículo asignado</h3><div class="manage-assigned-icon">${portalIcon('grid')}</div><h2>Toyota Corolla</h2><p>VEH-001 · Automóvil</p>${btn('Vehicles','Ver flota')}</section></div></div>`}
function courseGroupsPage(){const {row:r,id}=selectedRecord('Courses');return `<div class="portal-page-heading"><div><span class="portal-kicker">CURSOS / DETALLE Y GRUPOS</span><h1>${r[0]} · ${r[1]}</h1><p>Organiza el programa y acompaña a cada grupo.</p></div>${btn('Courses','Volver a cursos')}</div>${managementMetrics([['Estudiantes inscritos',String(r[3])],['Grupos activos','3'],['Instructores','2'],['Avance medio','64%']])}<div class="manage-detail-layout"><div><section class="manage-panel"><div class="manage-panel-head"><div><span class="manage-status"><i></i>Programa activo</span><h2 style="margin-top:12px">Información del curso</h2></div><span class="manage-counter">${id}</span></div><form onsubmit="event.preventDefault();document.getElementById('course-save-status').textContent='Cambios preparados en la demostración.'"><div class="reg-fields"><label>Nombre del curso<input value="${r[0]}" required></label><label>Nivel / modalidad<select>${['Básico','Avanzado','Intensivo','Refuerzo'].map(t=>`<option ${t===r[1]?'selected':''}>${t}</option>`).join('')}</select></label><label>Horas teóricas<input type="number" min="0" placeholder="Por definir"></label><label>Horas prácticas<input type="number" min="0" placeholder="Por definir"></label><label>Precio<input type="number" min="0" placeholder="Por definir"></label><label>Estado<select><option>Activo</option><option>Pendiente</option><option>Inactivo</option></select></label></div><label class="reg-notes">Descripción<textarea rows="3">Formación teórica y práctica para estudiantes que comienzan a conducir.</textarea></label><div class="reg-actions"><button class="primary">Guardar cambios</button></div><p id="course-save-status" role="status"></p></form></section><section class="manage-panel"><div class="manage-panel-head"><div><h2>Grupos del curso</h2><p>Horarios, cupos e instructores.</p></div><button class="primary" onclick="document.getElementById('new-group-dialog').showModal()">+ Crear grupo</button></div><div class="manage-table-scroll"><table class="manage-table"><thead><tr><th>Grupo</th><th>Horario</th><th>Instructor</th><th>Cupos</th><th>Estado</th></tr></thead><tbody>${[['Matutino A','08:00–10:00','Roberto García','6 / 8'],['Vespertino A','14:00–16:00','Ana Martínez','8 / 8'],['Sabatino','09:00–11:00','Roberto García','4 / 8']].map(([n,time,person,seats])=>`<tr><td><strong>${n}</strong></td><td>${time}</td><td>${link('Ficha del instructor',person,mode,recordId('Instructors',Math.max(0,managementData.Instructors.rows.findIndex(r=>r[0]===person))))}</td><td>${seats}</td><td><span class="manage-status"><i></i>Activo</span></td></tr>`).join('')}</tbody></table></div></section></div><div class="manage-detail-side"><section class="manage-panel"><h3>Temario del programa</h3><ol class="manage-syllabus">${['Señalización y normas','Control del vehículo','Maniobras y estacionamiento','Circulación segura','Evaluación final'].map(t=>`<li>${t}</li>`).join('')}</ol></section><section class="manage-panel manage-soft-panel"><h3>Seguimiento del aprendizaje</h3><p>Evalúa al estudiante al completar sus horas y recomienda refuerzo según su preparación.</p>${btn('Reportes y resultados','Ver resultados')}</section></div></div><dialog class="manage-dialog" id="new-group-dialog"><form onsubmit="event.preventDefault();document.getElementById('group-feedback').textContent='Grupo preparado en la demostración.'"><div class="manage-panel-head"><h2>Crear grupo</h2><button type="button" onclick="document.getElementById('new-group-dialog').close()" aria-label="Cerrar">×</button></div>${fields(['Nombre del grupo','Horario'])}<label>Cupos<input type="number" min="1" required></label><button class="primary">Preparar grupo</button><p id="group-feedback" role="status"></p></form></dialog>`}

const refreshedPages=['Ficha del vehículo','Calendario de clases','Detalle de clase','Pagos','Contenido educativo','Banco de preguntas','Reportes y resultados','Usuarios y configuración'];
function adminHeading(title,description,action=''){return `<div class="portal-page-heading"><div><span class="portal-kicker">ADMINISTRACIÓN / ${title.toUpperCase()}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function adminInput(label,value='',type='text'){return `<label>${label}<input type="${type}" ${value?'value="'+value+'"':'placeholder="Por completar"'} ${type==='number'?'min="0"':''}></label>`}
function adminSelect(label,values){return `<label>${label}<select>${values.map(v=>`<option>${v}</option>`).join('')}</select></label>`}
function adminDemoForm(content,button='Guardar cambios'){return `<form onsubmit="event.preventDefault();this.querySelector('[role=status]').textContent='Cambios preparados en la demostración. No se han guardado en una base de datos.'">${content}<div class="reg-actions"><button class="primary">${button}</button></div><p role="status" class="admin-demo-status"></p></form>`}
function adminRows(headers,rows){return `<div class="manage-table-scroll"><table class="manage-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function adminBadge(t){return `<span class="manage-status"><i></i>${t}</span>`}
function openAdminDialog(title,kind){const dialog=document.getElementById('admin-action-dialog');dialog.querySelector('h2').textContent=title;dialog.querySelector('.admin-dialog-fields').innerHTML=kind==='payment'?`<div class="reg-fields">${adminSelect('Estudiante',people)}${adminInput('Importe','','number')}${adminSelect('Método',['Efectivo','Transferencia','Otro'])}${adminInput('Referencia')}</div>`:kind==='question'?`<div class="reg-fields">${adminInput('Pregunta')}${adminSelect('Tema',['Señalización','Seguridad vial','Prioridad de paso'])}${adminInput('Respuesta correcta')}${adminInput('Alternativa 1')}${adminInput('Alternativa 2')}${adminInput('Fuente y fecha de revisión')}</div>`:kind==='class'?`<div class="reg-fields">${adminSelect('Estudiante',people)}${adminSelect('Instructor',['Roberto García','Ana Martínez'])}${adminSelect('Vehículo',['Toyota Corolla','Honda CB125'])}${adminInput('Fecha','','date')}${adminInput('Hora','','time')}${adminInput('Duración (minutos)','','number')}</div>`:`<div class="reg-fields">${adminInput('Título')}${adminSelect('Tema',['Señalización','Seguridad vial','Conducción'])}${adminSelect('Tipo',['Lección','Video','Documento'])}${adminInput('Enlace del recurso','','url')}</div>`;dialog.querySelector('[role=status]').textContent='';dialog.showModal()}
function adminDialog(){return `<dialog id="admin-action-dialog" class="manage-dialog"><div class="manage-panel-head"><h2>Nuevo registro</h2><button aria-label="Cerrar" onclick="document.getElementById('admin-action-dialog').close()">×</button></div>${adminDemoForm('<div class="admin-dialog-fields"></div>','Preparar registro')}</dialog>`}
function adminFilterRows(input){const args=arguments;return animateFiltering(arguments[0].closest('.manage-panel'),'tbody tr,.admin-resource',()=>adminFilterRowsImmediate(...args))}
function adminFilterRowsImmediate(input){const panel=input.closest('.manage-panel');const term=input.value.toLowerCase();panel.querySelectorAll('tbody tr,.admin-resource').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(term))}
function remainingAdminPage(){let content='';if(page==='Ficha del vehículo'){const {row:r,id}=selectedRecord('Vehicles');content=adminHeading('Ficha del vehículo','Datos, disponibilidad y mantenimiento de tu flota.',btn('Vehicles','Volver a vehículos'))+managementMetrics([['Estado',r[4]],['Clases esta semana','12'],['Kilometraje','24,800'],['Avisos activos','1']])+`<div class="manage-detail-layout"><div><section class="manage-panel"><div class="manage-person-hero"><div class="admin-vehicle-icon">${portalIcon('grid')}</div><div>${adminBadge(r[4])}<h2>${r[0]}</h2><p>${id} · ${r[1]}</p></div></div></section><section class="manage-panel"><div class="manage-panel-head"><h2>Información del vehículo</h2></div>${adminDemoForm(`<div class="reg-fields">${adminInput('Marca y modelo',r[0])}${adminInput('Identificación',id)}${adminInput('Matrícula')}${adminSelect('Tipo',[courseCategories[selectedRecord('Vehicles').index][0],...courseCategories.filter((_,i)=>i!==selectedRecord('Vehicles').index).map(c=>c[0])])}${adminSelect('Transmisión',['Manual','Automática'])}${adminInput('Kilometraje','24800','number')}${adminSelect('Estado',[r[4],...['Disponible','En uso','Mantenimiento'].filter(x=>x!==r[4])])}${adminSelect('Instructor asignado',[r[3],...managementData.Instructors.rows.map(x=>x[0]).filter(x=>x!==r[3]),'Sin asignar'])}</div>`)}</section><section class="manage-panel"><h2>Historial de mantenimiento</h2>${adminRows(['Servicio','Fecha','Estado'],[['Revisión general','Por confirmar',adminBadge('Completado')],['Cambio de aceite','Por confirmar',adminBadge('Completado')],['Próxima revisión','Por programar',adminBadge('Pendiente')]])}</section></div><div><section class="manage-panel"><h3>Documentos y vencimientos</h3>${adminDemoForm(`<div class="reg-fields admin-one-col">${adminInput('Vencimiento del seguro','','date')}${adminInput('Inspección técnica','','date')}${adminInput('Documento / enlace','','url')}</div>`)}</section><section class="manage-panel manage-soft-panel"><h3>Próxima asignación</h3><p>Clase práctica · María López<br>Instructor · Roberto García</p>${btn('Calendario de clases','Ver calendario')}</section></div></div>`}
if(page==='Calendario de clases'){content=adminHeading(page,'Organiza horarios, instructores y vehículos.',`<button class="primary" onclick="openAdminDialog('Programar clase','class')">+ Programar clase</button>`)+managementMetrics([['Clases programadas','24'],['Para hoy','8'],['Instructores activos','6'],['Reprogramaciones','2']])+`<section class="manage-panel"><div class="manage-panel-head"><h2>Agenda de la semana</h2><span class="manage-counter">Semana de ejemplo</span></div><div class="admin-calendar">${['Lunes','Martes','Miércoles','Jueves','Viernes'].map((day,i)=>`<div class="admin-calendar-day"><h3>${day}</h3><span class="admin-day-date">${9+i}</span>${[0,1,2].slice(0,i%2?2:3).map((_,j)=>`<a class="admin-calendar-event ${j===1?'alternate':''}" href="${route('Detalle de clase')}"><strong>${['08:00','10:00','14:00'][j]}</strong><span>${people[(i+j)%4]}</span><small>${j===1?'Teoría vial':'Clase práctica'}</small><small>${j===1?'Ana Martínez':'Roberto García'}</small></a>`).join('')}</div>`).join('')}</div><p class="admin-hint">Selecciona una clase para consultar la asignación y registrar el seguimiento.</p></section>`}
if(page==='Detalle de clase'){content=adminHeading('Detalle de clase','Preparación, asistencia y observaciones de la sesión.',btn('Calendario de clases','Volver a la agenda'))+`<div class="manage-detail-layout"><div><section class="manage-panel"><div class="manage-panel-head"><div>${adminBadge('Programada')}<h2 style="margin-top:12px">Clase práctica · Automóviles</h2><p>Sesión de ejemplo · 08:00–09:00</p></div><span class="manage-counter">CLS-001</span></div><div class="admin-class-summary">${[['Estudiante','María López'],['Instructor','Roberto García'],['Vehículo','Toyota Corolla'],['Duración','60 minutos']].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('')}</div></section><section class="manage-panel"><h2>Asistencia y seguimiento</h2>${adminDemoForm(`<div class="reg-fields">${adminSelect('Asistencia',['Por registrar','Presente','Ausente'])}${adminSelect('Estado de la clase',['Programada','Completada','Reprogramada','Cancelada'])}${adminSelect('Valoración',['Por evaluar','Necesita práctica','En progreso','Objetivo alcanzado'])}${adminSelect('Refuerzo recomendado',['Por definir','No','Sí'])}</div><label class="reg-notes">Observaciones<textarea rows="4" placeholder="Maniobras practicadas, avances y recomendaciones…"></textarea></label>`,'Guardar seguimiento')}</section></div><div><section class="manage-panel"><h3>Objetivos de la sesión</h3><ul class="admin-checklist"><li>Preparación del vehículo</li><li>Control y maniobras</li><li>Observación del entorno</li><li>Conducción segura</li></ul></section><section class="manage-panel manage-soft-panel"><h3>Reprogramar sesión</h3>${adminDemoForm(`<div class="reg-fields admin-one-col">${adminInput('Nueva fecha','','date')}${adminInput('Nueva hora','','time')}</div>`,'Preparar cambio')}</section></div></div>`}
if(page==='Pagos'){content=adminHeading('Pagos','Consulta cobros y saldos por estudiante.',`<button class="primary" onclick="openAdminDialog('Registrar pago','payment')">+ Registrar pago</button>`)+managementMetrics([['Cobrado este mes','24,000'],['Saldo pendiente','6,000'],['Pagos registrados','18'],['Por revisar','3']])+`<section class="manage-panel"><div class="manage-panel-head"><h2>Movimientos recientes</h2><span class="manage-counter">Importes y moneda de ejemplo</span></div><input type="search" placeholder="Buscar por estudiante, estado o referencia…" aria-label="Buscar pagos" oninput="adminFilterRows(this)">${adminRows(['Estudiante','Concepto','Importe','Método','Estado','Ficha'],people.map((n,i)=>[n,'Cuota del curso',['1,500','2,000','1,000','1,500'][i],i%2?'Transferencia':'Efectivo',adminBadge(i===2?'Pendiente':'Registrado'),link('Ficha del estudiante','Ver estudiante ↗',mode,personRecordId(n))]))}<div class="manage-table-footer"><span>Los comprobantes y cobros reales se conectarán en el sistema completo.</span><span>1 de 1</span></div></section>`}
if(page==='Contenido educativo'){content=adminHeading(page,'Organiza lecciones y recursos para el portal del estudiante.',`<button class="primary" onclick="openAdminDialog('Crear recurso','resource')">+ Crear recurso</button>`)+managementMetrics([['Recursos','18'],['Publicados','12'],['Borradores','6'],['Temas','4']])+`<section class="manage-panel"><div class="manage-panel-head"><h2>Biblioteca de aprendizaje</h2>${btn('Banco de preguntas','Banco de preguntas')}</div><input type="search" aria-label="Buscar recursos" placeholder="Buscar título, tema o tipo…" oninput="adminFilterRows(this)"><div class="admin-resource-grid">${[['Señales de tránsito','Lección','Señalización'],['Conducción segura','Video','Seguridad vial'],['Rotondas e intersecciones','Lección','Prioridad de paso'],['Preparación del vehículo','Documento','Conducción']].map(([title,type,theme],i)=>`<article class="admin-resource"><span class="admin-resource-icon">${portalIcon('book')}</span>${adminBadge(i===3?'Borrador':'Publicado')}<h3>${title}</h3><p>${theme} · ${type}</p><div class="admin-resource-footer"><span>Contenido de ejemplo</span><button onclick="openAdminDialog('Editar recurso','resource')">Editar ↗</button></div></article>`).join('')}</div></section>`}
if(page==='Banco de preguntas'){content=adminHeading(page,'Prepara preguntas, respuestas y explicaciones por tema.',`<button class="primary" onclick="openAdminDialog('Nueva pregunta','question')">+ Añadir pregunta</button>`)+managementMetrics([['Preguntas','60'],['Revisadas','42'],['Por revisar','18'],['Temas','4']])+`<section class="manage-panel"><div class="manage-panel-head"><h2>Preguntas del simulador</h2><span class="manage-counter">Banco ilustrativo</span></div><input type="search" aria-label="Buscar preguntas" placeholder="Buscar por pregunta o tema…" oninput="adminFilterRows(this)">${adminRows(['Pregunta','Tema','Tipo','Estado','Acción'],questions.map((q,i)=>[q[0],['Seguridad vial','Conducción','Preparación'][i],'Selección única',adminBadge('Por revisar'),`<button onclick="openAdminDialog('Editar pregunta','question')">Editar ↗</button>`]))}</section><section class="manage-panel manage-soft-panel"><h3>Control del contenido</h3><p>Registra la fuente y fecha de revisión. Las preguntas de demostración deben sustituirse por contenido verificado para la jurisdicción de la escuela.</p></section>`}
if(page==='Reportes y resultados'){content=adminHeading(page,'Consulta el avance del aprendizaje y detecta temas por reforzar.')+managementMetrics([['Estudiantes evaluados','36'],['Promedio de resultados','78%'],['Intentos realizados','124'],['Requieren refuerzo','8']])+`<div class="manage-detail-layout"><div><section class="manage-panel"><div class="manage-panel-head"><h2>Resultados por tema</h2><span class="manage-counter">Resumen de ejemplo</span></div>${[['Señalización',85],['Prioridad de paso',72],['Rotondas',64],['Conducción segura',90]].map(([title,n])=>`<div class="admin-report-row"><div><span>${title}</span><strong>${n}%</strong></div><div class="admin-report-bar"><i style="width:${n}%"></i></div></div>`).join('')}</section><section class="manage-panel"><h2>Seguimiento por estudiante</h2>${adminRows(['Estudiante','Progreso','Resultado','Acción'],people.map((n,i)=>[n,[68,45,30,100][i]+'%',[80,72,64,92][i]+'%',link('Ficha del estudiante','Ver ficha ↗',mode,personRecordId(n))]))}</section></div><div><section class="manage-panel"><h3>Distribución de resultados</h3><div class="admin-result-ring"><strong>78<span>%</span></strong></div><p style="text-align:center">Promedio del grupo</p><div class="admin-legend"><span>Objetivo alcanzado</span><strong>28</strong></div><div class="admin-legend"><span>Refuerzo recomendado</span><strong>8</strong></div></section><section class="manage-panel manage-soft-panel"><h3>Próximo paso</h3><p>Consulta los resultados individuales y coordina práctica adicional con el instructor.</p>${btn('Students','Ver estudiantes')}</section></div></div>`}
if(page==='Usuarios y configuración'){content=adminHeading('Usuarios y configuración','Administra perfiles, acceso y preferencias de la escuela.',btn('Registrar usuario','Registrar usuario'))+`<div class="manage-detail-layout"><div><section class="manage-panel"><h2>Datos de la escuela</h2>${adminDemoForm(`<div class="reg-fields">${adminInput('Nombre de la escuela','Nexo Drive')}${adminInput('Correo de contacto','','email')}${adminInput('Teléfono','','tel')}${adminInput('Ciudad')}${adminSelect('Moneda',['Por configurar','USD','Córdoba','Euro','Otra'])}${adminSelect('Idioma',['English','Español'])}</div>`)}</section><section class="manage-panel"><h2>Usuarios y roles</h2>${adminRows(['Usuario','Rol','Estado','Acción'],[['Administración','Administrador',adminBadge('Activo'),link('Registrar usuario','Crear perfil ↗')],['Roberto García','Instructor',adminBadge('Activo'),link('Ficha del instructor','Ver ficha ↗')],['María López','Estudiante',adminBadge('Activo'),link('Ficha del estudiante','Ver ficha ↗')]])}</section><section class="manage-panel"><h2>Notificaciones</h2>${adminDemoForm(`<div class="admin-toggles">${['Recordatorios de clases','Avisos de pagos pendientes','Resultados y progreso'].map(t=>`<label><span>${t}</span><input type="checkbox" checked></label>`).join('')}</div>`)}</section></div><div><section class="manage-panel"><h3>Permisos por rol</h3><div class="admin-permission"><strong>Administrador</strong><p>Gestión de la escuela y su contenido.</p></div><div class="admin-permission"><strong>Instructor</strong><p>Agenda y estudiantes asignados.</p></div><div class="admin-permission"><strong>Estudiante</strong><p>Aprendizaje y resultados propios.</p></div></section><section class="manage-panel manage-soft-panel"><h3>Acceso y seguridad</h3><p>La autenticación, recuperación de contraseña y permisos reales se conectarán en la implementación del sistema.</p><span class="reg-demo-pill">Modo demostración</span></section></div></div>`}return content+adminDialog()}

const learningPages=['Mi agenda','Detalle de clase','Mis estudiantes','Ficha y progreso','Mi perfil','Simulador','Práctica por tema','Examen completo','Resultado y explicación','Mis resultados','Detalle del intento','Material de estudio','Lección o recurso'];
function learningHeading(title,description,action=''){return adminHeading(title,description,action).replace('ADMINISTRACIÓN /',names[mode].toUpperCase()+' /')}
function mappedAdminPage(target){const previous=page;page=target;try{return remainingAdminPage().replace('ADMINISTRACIÓN /',names[mode].toUpperCase()+' /').replaceAll(route('Calendario de clases'),route('Mi agenda'))}finally{page=previous}}
